# DK ETT.  Ebeltoft - Trustrup
#
let et = path("d3.dk.ett");

with detail = 4, railway = :first :pax :removed {
    with link = "point.dk.Ebeltoft", railway = :station {
        track(et[:ebe - 200m, :ebe + 0.5sw]);
        marker(:right :de.bf, et[:ebe] >> 0.5mt);
        station(:right, et[:ebe] >> 0.5mt >> 1sh + (1.8dt, 1.5dt),
            span(:bold, "Ebeltoft"), "ETT: 0,0"
        );
    }

    with link = "line.dk.ETT" {
        track(et[:ebe + 0.49sw, :vib - 0.49sw]);
    }

    with link = "point.dk.Vibæk", railway = :station {
        track(et[:vib - 0.5sw, :vib + 0.5sw]);
        marker(:left :de.hp, et[:vib] << 0.5mt);
        station(:left, et[:vib] << 0.5mt << 1sh + (-1.4dt, 1.2dt),
            "Vibæk", "ETT: 1,4"
        );
    }

    with link = "line.dk.ETT" {
        track(et[:vib + 0.49sw, :vib + 0.81km]);
        line_label(:left:se, et[:vib + 0.8km] << 0.5mt, "ETT");
        track(et[:vib + 0.79km, :dra - 0.49sw]);
    }

    with link = "point.dk.Dråby", railway = :station {
        track(et[:dra - 0.5sw, :dra + 0.5sw]);
        marker(:right :de.hp, et[:dra] >> 0.5mt);
        station(:right, et[:dra] >> 0.5mt >> 1sh + (1.8dt, 1.6dt),
            "Dråby", "ETT: 3,1"
        );
    }

    with link = "line.dk.ETT" {
        track(et[:dra + 0.49sw, :ska - 0.49sw]);
    }

    with link = "point.dk.Skærsø", railway = :station {
        track(et[:ska - 0.5sw, :ska + 0.5sw]);
        marker(:right :de.bf, et[:ska] >> 0.5mt);
        station(:right, et[:ska] >> 0.5mt >> 1sh + (2.0dt, 2.0dt),
            "Skærsø", "ETT: 4,9"
        );
    }

    with link = "line.dk.ETT" {
        track(et[:ska + 0.49sw, :stu - 0.49sw]);
    }

    with link = "point.dk.Stubbe", railway = :station {
        track(et[:stu - 0.5sw, :stu + 0.5sw]);
        marker(:right :de.hp, et[:stu] >> 0.5mt);
        station(:right, et[:stu] >> 0.5mt >> 1sh + (1.5dt, 1.3dt),
            "Stubbe", "ETT: 7,0"
        );
    }

    with link = "line.dk.ETT" {
        track(et[:stu + 0.49sw, :gra - 0.49sw]);
    }

    with link = "point.dk.Gravlev", railway = :station {
        track(et[:gra - 0.5sw, :gra + 0.5sw]);
        marker(:left :de.hp, et[:gra] << 0.5mt);
        marker(:left :de.exbf, et[:gra] << 0.5mt);
        station(:left, et[:gra] << 0.5mt << 1.4sh + (-2.0dt, 0.7dt),
            "Gravlev", "ETT: 9,5"
        );
    }

    with link = "line.dk.ETT" {
        track(et[:gra + 0.49sw, :hyl - 0.49sw]);
    }

    with link = "point.dk.Hyllested", railway = :station {
        track(et[:hyl - 0.5sw, :hyl + 0.5sw]);
        marker(:right :de.bf, et[:hyl] >> 0.5mt);
        station(:right, et[:hyl] >> 0.5mt >> 1sh + (2.0dt, 2.0dt),
            "Hyllested", "ETT: 12,1"
        );
    }

    with link = "line.dk.ETT" {
        track(et[:hyl + 0.49sw, :ros - 0.49sw]);
    }

    with link = "point.dk.Rosmus", railway = :station {
        track(et[:ros - 0.5sw, :ros + 0.5sw]);
        marker(:left :de.hp, et[:ros] << 0.5mt);
        marker(:left :de.exbf, et[:ros] << 0.5mt);
        station(:left, et[:ros] << 0.5mt << 1.4sh + (-2.3dt, 0.2dt),
            "Rosmus", "ETT: 14,4"
        );
    }

    with link = "line.dk.ETT" {
        track(et[:ros + 0.49sw, :nyb - 0.49sw]);
    }

    with link = "point.dk.Ny-Balle", railway = :station {
        track(et[:nyb - 0.5sw, :nyb + 0.5sw]);
        marker(:left :de.bf, et[:nyb] << 0.5mt);
        station(:left, et[:nyb] << 0.5mt << 1sh + (-1.8dt, 0.8dt),
            "Ny Balle", "ETT: 15,8"
        );
    }

    with link = "line.dk.ETT" {
        track(et[:nyb + 0.49sw, :bal - 0.49sw]);
    }

    with link = "point.dk.Balle", railway = :station {
        track(et[:bal - 0.5sw, :bal + 0.5sw]);
        marker(:right :de.bf, et[:bal] >> 0.5mt);
        station(:right:left_align, et[:bal] >> 0.5mt >> 1sh + (1.5dt, 1.2dt),
            "Balle", "ETT: 16,9"
        );
    }

    with link = "line.dk.ETT" {
        track(et[:bal + 0.49sw, :bal + 1.01km]);
        line_label(:right:sw, et[:bal + 1km] >> 0.5mt, "ETT");
        track(et[:bal + 0.99km, :att - 0.49sw]);
    }

    with link = "point.dk.Attrup-Kær", railway = :station {
        track(et[:att - 0.5sw, :att + 0.5sw]);
        marker(:left :de.hp, et[:att] << 0.5mt);
        station(:bottom, et[:att] << 0.5mt << 1sh + (-2dt, 1.2dt),
            "Attrup Kær", "ETT: 19,5"
        );
    }

    with link = "line.dk.ETT" {
        track(et[:att + 0.49sw, :gre - 0.49sw]);
    }

    with link = "point.dk.Grenå-Landevej", railway = :station {
        track(et[:gre - 0.5sw, :gre + 0.5sw]);
        marker(:right :de.hp, et[:gre] >> 0.5mt);
        station(:left, et[:gre] << 0.5mt + (-1.3dt, 1.3dt),
            "Grenå Landevej", "ETT: ??"
        );
    }

    with link = "line.dk.ETT" {
        track(:lor,
                et[:gre + 0.49sw, :gre + 0.5sw]
            ..  et[:tru.ye, :tru.ye + 0.1dl] >> 1mo
        );
    }
}

